				{ model: "claude-fable-5-1", reasoning: "low" },
			],
		},
	],
};

export function resolveEffortProviders(
	ctx: Pick<ExtensionContext, "modelRegistry">,
	effort: ModelEffort,
): EffortProviderCandidates[] {
	const available = new Map(ctx.modelRegistry.getAvailable().map((model) => [`${model.provider}/${model.id}`, model]));
	return MODEL_PREFERENCES[effort].flatMap((preference) => {
		const candidates = preference.models.flatMap(({ model, reasoning }) => {
			const availableModel = available.get(`${preference.provider}/${model}`);
			return availableModel ? [{ model: availableModel, reasoning }] : [];
		});
		return candidates.length
			? [
					{
						provider: preference.provider,
						label: ctx.modelRegistry.getProviderDisplayName(preference.provider),
						candidates,
					},
				]
			: [];
	});
}

export function resolveEffortCandidates(
	ctx: Pick<ExtensionContext, "modelRegistry" | "model" | "cwd" | "isProjectTrusted">,
	effort: ModelEffort,
	options: EffortCandidateOptions,
): Promise<ModelCandidate[]> {
	const preferences = options.preferredProvider
		? [
				...MODEL_PREFERENCES[effort].filter(({ provider }) => provider === options.preferredProvider),
				...MODEL_PREFERENCES[effort].filter(({ provider }) => provider !== options.preferredProvider),
			]
		: MODEL_PREFERENCES[effort];
	return resolveCandidates(
		ctx,
		preferences.flatMap((preference) =>
			preference.models.map((model) => ({ provider: preference.provider, ...model })),
		),
		options.includeParentModel,
	);
}

import { randomUUID } from "node:crypto";
import {
	type Api,
	type AssistantMessage,
	type Message,
	type Model,
	type ThinkingLevel,
	type Tool,
} from "@earendil-works/pi-ai";
import type { ExtensionContext } from "@earendil-works/pi-coding-agent";
import { loadTauExtensionSettings, updateTauExtensionSettings } from "../settings/load.ts";
import { errorText, truncAt } from "../text.ts";
import modelFallbackSettings from "./settings.ts";
import type { ModelCandidate } from "./types.ts";

const MAX_ATTEMPTS = 5;
const MAX_TOOL_ATTEMPTS = 2;
const SEVEN_DAYS_MS = 604_800_000;

interface GenerationContext {
	ui: ExtensionContext["ui"];
	modelRegistry: ExtensionContext["modelRegistry"];
	signal: AbortSignal | undefined;
}

interface ModelFallbackOptions {
	statusKey?: string;
	notifyOnFallback?: boolean;
	maxAttempts?: number;
	onStatus?: (status: string) => void | Promise<void>;
}

export async function resolveCandidates(
	ctx: Pick<ExtensionContext, "modelRegistry" | "model" | "cwd" | "isProjectTrusted">,
	preferredModels: ReadonlyArray<{ provider: string; model: string; reasoning: ThinkingLevel | undefined }>,
	includeParentModel: boolean,
): Promise<ModelCandidate[]> {
	const settings = await loadTauExtensionSettings(ctx, modelFallbackSettings);
	const candidates: ModelCandidate[] = [];
	const seen = new Set<string>();
	const blocked = currentBlockedProviders(settings.cooldowns ?? {});

	const add = (model: Model<Api>, reasoning: ThinkingLevel | undefined): void => {
		if (blocked.has(model.provider)) return;
		const key = `${model.provider}/${model.id}`;
		if (seen.has(key)) return;

		if (!ctx.modelRegistry.hasConfiguredAuth(model)) return;

		seen.add(key);
		candidates.push({ model, reasoning });
	};

	for (const preferred of preferredModels) {
		const model = ctx.modelRegistry.find(preferred.provider, preferred.model);
		if (model) add(model, preferred.reasoning);
	}
	if (includeParentModel && ctx.model) add(ctx.model, undefined);

	if (candidates.length === 0) throw new Error("No authenticated model available for generation.");
	return candidates;
}

export async function generateValidated<T>(
	ctx: GenerationContext,
	candidates: readonly ModelCandidate[],
	prompt: string,
	validate: (text: string) => T,
	correctionPrompt?: (error: Error, text: string) => string,
	options?: ModelFallbackOptions,
): Promise<T> {
	const { value } = await withModelFallback(ctx, candidates, options, (candidate) =>
		requestValidated(ctx, candidate, prompt, validate, correctionPrompt),
	);
	return value;
}

export async function generateToolValidated<T>(
	ctx: GenerationContext,
	candidates: readonly ModelCandidate[],
	prompt: string,
	tool: Tool,
	validate: (input: unknown) => T,
	correctionPrompt?: (error: Error, output: string) => string,
	options?: ModelFallbackOptions,
): Promise<{ value: T; candidate: ModelCandidate }> {
	return withModelFallback(ctx, candidates, options, (candidate) =>
		requestToolValidated(
			ctx,
			candidate,
			prompt,
			tool,
			validate,
			correctionPrompt,
			options?.maxAttempts ?? MAX_TOOL_ATTEMPTS,
		),
	);
}

async function noteCandidateFailure(
	ctx: GenerationContext,
	options: ModelFallbackOptions | undefined,
	label: string,
	message: string,
	hasMore: boolean,
): Promise<void> {
	if (!hasMore) return;
	await options?.onStatus?.(`Model failed (${label}); trying next model`);
	if (options?.notifyOnFallback ?? false) {
		ctx.ui.notify(`Model failed (${label}): ${message}\nTrying next model.`, "info");
	}
}

async function withModelFallback<T>(
	ctx: GenerationContext,
	candidates: readonly ModelCandidate[],
	options: ModelFallbackOptions | undefined,
	request: (candidate: ModelCandidate) => Promise<T>,
): Promise<{ value: T; candidate: ModelCandidate }> {
	const failures: string[] = [];
	const statusKey = options?.statusKey;

	for (const [index, candidate] of candidates.entries()) {
		const label = `${candidate.model.provider}/${candidate.model.id}`;
		if (statusKey) ctx.ui.setStatus(statusKey, `generating (${label})`);
		await options?.onStatus?.(`Generating with ${label}`);
		try {
			return { value: await request(candidate), candidate };
		} catch (error) {
			if (ctx.signal?.aborted) throw new Error("Cancelled.");
			if (shouldCooldownProvider(error)) await markProviderUnavailable(candidate.model.provider);
			const message = errorText(error);
			failures.push(`- ${label}: ${message}`);
			await noteCandidateFailure(ctx, options, label, message, index < candidates.length - 1);
		}
	}

	throw new Error(["Model generation failed for all candidates:", ...failures].join("\n"));
}

function throwUnlessRetryableStopError(response: AssistantMessage, attempt: number, maxAttempts: number): void {
	if (response.stopReason !== "error") return;
	const error = new Error(response.errorMessage || "model returned an error");
	if (attempt < maxAttempts && !shouldCooldownProvider(error)) return;
	throw error;
}

function pushCorrection(
	messages: Message[],
	error: Error,
	output: string,
	correctionPrompt: (error: Error, output: string) => string,
): void {
	messages.push({
		role: "user",
		content: [{ type: "text", text: correctionPrompt(error, truncAt(output, 4_000)) }],
		timestamp: Date.now(),
	});
}

function shouldRetryValidation(
	error: unknown,
	attempt: number,
	maxAttempts: number,
	correctionPrompt: ((error: Error, output: string) => string) | undefined,
): error is Error {
	return error instanceof Error && attempt < maxAttempts && correctionPrompt !== undefined;
}

async function requestValidated<T>(
	ctx: GenerationContext,
	candidate: ModelCandidate,
	prompt: string,
	validate: (text: string) => T,
	correctionPrompt?: (error: Error, text: string) => string,
): Promise<T> {
	const messages: Message[] = [{ role: "user", content: [{ type: "text", text: prompt }], timestamp: Date.now() }];
	const sessionId = randomUUID();

	for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
		const response = await completeCandidate(ctx, candidate, messages, sessionId);
		const text = responseText(response);
		try {
			throwUnlessRetryableStopError(response, attempt, MAX_ATTEMPTS);
			if (response.stopReason === "error") continue;
			return validate(text);
		} catch (error) {
			if (!shouldRetryValidation(error, attempt, MAX_ATTEMPTS, correctionPrompt) || !correctionPrompt) {
				throw error;
			}
			if (text) messages.push({ ...response, content: [{ type: "text", text }] });
			pushCorrection(messages, error, text, correctionPrompt);
		}
	}

	throw new Error("Model generation failed.");
}

function validateSingleToolCall(tool: Tool, toolCalls: readonly { name: string; arguments: unknown }[]): unknown {
	if (toolCalls.length !== 1) throw new Error(`Model must call ${tool.name} exactly once.`);
	const toolCall = toolCalls[0];
	if (!toolCall) throw new Error(`Model must call ${tool.name}.`);
	if (toolCall.name !== tool.name) throw new Error(`Model called ${toolCall.name}; expected ${tool.name}.`);
	return toolCall.arguments;
}

async function requestToolValidated<T>(
	ctx: GenerationContext,
	candidate: ModelCandidate,
	prompt: string,
	tool: Tool,
	validate: (input: unknown) => T,
	correctionPrompt?: (error: Error, output: string) => string,
	maxAttempts = MAX_TOOL_ATTEMPTS,
): Promise<T> {
	const messages: Message[] = [{ role: "user", content: [{ type: "text", text: prompt }], timestamp: Date.now() }];
	const sessionId = randomUUID();

	for (let attempt = 1; attempt <= maxAttempts; attempt++) {
		const response = await completeCandidate(ctx, candidate, messages, sessionId, [tool]);
		const text = responseText(response);
		const toolCalls = response.content.flatMap((part) => (part.type === "toolCall" ? [part] : []));
		const output = text || formatToolCalls(toolCalls);
		try {
			throwUnlessRetryableStopError(response, attempt, maxAttempts);
			if (response.stopReason === "error") continue;
			return validate(validateSingleToolCall(tool, toolCalls));
		} catch (error) {
			if (!shouldRetryValidation(error, attempt, maxAttempts, correctionPrompt) || !correctionPrompt) {
				throw error;
			}
			pushCorrection(messages, error, output, correctionPrompt);
		}
	}

	throw new Error("Model generation failed.");
}

function completeCandidate(
	ctx: GenerationContext,
	candidate: ModelCandidate,
	messages: readonly Message[],
	sessionId: string,
	tools?: Tool[],
): Promise<AssistantMessage> {
	return ctx.modelRegistry
		.streamSimple(candidate.model, tools ? { messages: [...messages], tools } : { messages: [...messages] }, {
			signal: ctx.signal,
			reasoning: candidate.reasoning,
			sessionId,
		})
		.result();
}

function responseText(response: AssistantMessage): string {
	if (response.stopReason === "aborted") throw new Error("Cancelled.");
	return response.content.flatMap((part) => (part.type === "text" ? [part.text] : [])).join("\n");
}

function formatToolCalls(toolCalls: readonly { name: string; arguments: unknown }[]): string {
	if (toolCalls.length === 0) return "(no tool call)";
	try {
		return JSON.stringify(
			toolCalls.map((call) => ({ name: call.name, arguments: call.arguments })),
			null,
			2,
		);
	} catch {
		return "(tool call arguments unavailable)";
	}
}

